#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class KeyboardEnqueueTask final {
public:enum class Stage{ReadHead,Extend,Bind,Add,WriteEvent,Advance,Mask,WriteHead,Return,Complete};explicit KeyboardEnqueueTask(uint16_t event=0):event_(event){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned offset()const{return head_;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::ReadHead:return 9+c.read;case Stage::Bind:return 9;case Stage::WriteEvent:return 3+c.write;case Stage::Mask:return 6;case Stage::WriteHead:return 9+c.write;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::ReadHead:head_=uint16_t(read());break;case Stage::WriteEvent:write(false,head_,event_);break;case Stage::Advance:head_=uint16_t(head_+2);break;case Stage::Mask:head_&=0x7e;break;case Stage::WriteHead:write(true,0,head_);break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::ReadHead;uint16_t head_=0,event_;};
class KeyboardDequeueTask final {
public:enum class Stage{Retain,ReadTail,ReadHead,Compare,Select,Empty,RestoreEmpty,ReturnEmpty,RetainPointer,Bind,Extend,Add,Advance,Mask,WriteTail,ReadEvent,RestorePointer,Restore,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}uint16_t event()const{return event_;}unsigned offset()const{return tail_;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::Retain:case Stage::RetainPointer:return c.pushLong;case Stage::ReadTail:case Stage::ReadHead:return 9+c.read;case Stage::Empty:case Stage::Mask:return 6;case Stage::RestoreEmpty:case Stage::RestorePointer:case Stage::Restore:return c.popLong;case Stage::ReturnEmpty:case Stage::Return:return c.ret;case Stage::Bind:return 9;case Stage::WriteTail:return 9+c.write;case Stage::ReadEvent:return 3+c.read;case Stage::Complete:return 0;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::ReadTail:tail_=uint16_t(read(false));break;case Stage::ReadHead:head_=uint16_t(read(true));break;case Stage::Select:if(tail_!=head_)next=Stage::RetainPointer;break;case Stage::Empty:event_=0xff00;break;case Stage::ReturnEmpty:case Stage::Return:next=Stage::Complete;break;case Stage::WriteTail:write(uint16_t(tail_+2)&0x7e);break;case Stage::ReadEvent:event_=uint16_t(read(false));break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Retain;uint16_t tail_=0,head_=0,event_=0;};
class KeyboardResetTask final {
public:enum class Stage{Scan,ClearChild,Retain,Clear,WriteHead,WriteTail,Restore,Return,Complete};explicit KeyboardResetTask(bool initialize=false):stage_(initialize?Stage::Scan:Stage::Retain),initialize_(initialize){}Stage stage()const{return stage_;}bool initialize()const{return initialize_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Scan:case Stage::ClearChild:return c.shortCall;case Stage::Retain:return c.pushWord;case Stage::WriteHead:case Stage::WriteTail:return 9+c.write;case Stage::Restore:return c.popWord;case Stage::Return:return c.ret;default:return 3;}}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Scan:waiting_=true;break;case Stage::ClearChild:waiting_=true;next=Stage::Return;break;case Stage::WriteHead:write(true,0);break;case Stage::WriteTail:write(false,0);break;default:break;}stage_=next;return cost;}
private:Stage stage_;bool initialize_,waiting_=false;};
class KeyboardMapTask final {
public:enum class Stage{ClearPointer,CopyIndex,Read,Compare,Select,Enqueue,Return,Complete};explicit KeyboardMapTask(uint16_t event=0):event_(event),index_(uint8_t(event)){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned index()const{return index_;}uint16_t event()const{return event_;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Read:return 12+c.read;case Stage::Enqueue:return c.call;case Stage::Return:return c.ret;default:return 3;}}template<class R>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Read:event_=uint16_t((event_&0xff00)|uint8_t(read(index_)));break;case Stage::Select:if(uint8_t(event_)==255)next=Stage::Return;break;case Stage::Enqueue:waiting_=true;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::ClearPointer;uint16_t event_;unsigned index_;bool waiting_=false;};
class KeyboardScanTask final {
public:enum class Stage{RetainPointer,RetainSelect,RetainBits,RetainEventPointer,RetainMapPointer,RetainEvent,Input,WriteInput,BindHistory,ClearKey,ClearSelect,Rows,WriteSelect,RetainDelay,Delay,DecrementDelay,RepeatDelay,RestoreDelay,ReadHistory,ReadButtons,CompareBits,SelectChanges,WriteHistory,Bits,Shift,SelectChanged,Released,TestPressed,SelectPressed,Pressed,RetainKey,Enqueue,RestoreKey,AdvanceKey,DecrementBits,RepeatBits,SkipUnchanged,AdvanceUnchanged,AdvanceSelect,AdvanceHistory,DecrementRows,RepeatRows,Release,WriteRelease,Output,WriteOutput,RestoreEvent,RestoreMapPointer,RestoreEventPointer,RestoreBits,RestoreSelect,RestorePointer,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned row()const{return row_;}unsigned key()const{return key_;}uint16_t event()const{return uint16_t((word_&128?0:0x100)|key_);}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::RetainPointer:case Stage::RetainSelect:case Stage::RetainBits:case Stage::RetainEventPointer:case Stage::RetainMapPointer:case Stage::RetainEvent:return c.pushLong;case Stage::WriteInput:case Stage::WriteSelect:case Stage::ReadButtons:case Stage::WriteRelease:case Stage::WriteOutput:return 4;case Stage::BindHistory:return 9;case Stage::RetainDelay:return c.pushWord;case Stage::Delay:case Stage::Bits:return 6;case Stage::RestoreDelay:return c.popWord;case Stage::ReadHistory:return 3+c.read;case Stage::WriteHistory:return 3+c.write;case Stage::Enqueue:return c.shortCall;case Stage::RestoreEvent:case Stage::RestoreMapPointer:case Stage::RestoreEventPointer:case Stage::RestoreBits:case Stage::RestoreSelect:case Stage::RestorePointer:return c.popLong;case Stage::Return:return c.ret;default:return 3;}}template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::WriteInput:write(Write::Direction,0);break;case Stage::WriteSelect:write(Write::Select,row_*8);break;case Stage::Delay:delay_=3;break;case Stage::DecrementDelay:--delay_;break;case Stage::RepeatDelay:if(delay_)next=Stage::DecrementDelay;break;case Stage::ReadHistory:history_=uint8_t(read(false,row_));break;case Stage::ReadButtons:buttons_=uint8_t(read(true,row_));break;case Stage::CompareBits:word_=uint16_t(buttons_)<<8|uint8_t(history_^buttons_);break;case Stage::SelectChanges:if(!uint8_t(word_))next=Stage::AdvanceUnchanged;break;case Stage::WriteHistory:write(Write::History,buttons_);break;case Stage::Bits:bits_=8;break;case Stage::Shift:carry_=word_&1;word_>>=1;break;case Stage::SelectChanged:if(!carry_)next=Stage::AdvanceKey;break;case Stage::SelectPressed:if(word_&128)next=Stage::RetainKey;break;case Stage::Enqueue:waiting_=true;break;case Stage::AdvanceKey:++key_;break;case Stage::DecrementBits:--bits_;break;case Stage::RepeatBits:if(bits_)next=Stage::Shift;break;case Stage::SkipUnchanged:next=Stage::AdvanceSelect;break;case Stage::AdvanceUnchanged:key_+=8;break;case Stage::AdvanceHistory:++row_;break;case Stage::RepeatRows:if(row_<4)next=Stage::WriteSelect;break;case Stage::WriteRelease:write(Write::Select,0x40);break;case Stage::WriteOutput:write(Write::Direction,255);break;default:break;}stage_=next;return cost;}
 enum class Write{Direction,Select,History};
private:Stage stage_=Stage::RetainPointer;unsigned row_=0,key_=0,delay_=0,bits_=0;uint8_t history_=0,buttons_=0;uint16_t word_=0;bool waiting_=false,carry_=false;};
}
